import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/tmp/inventory.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        sku TEXT NOT NULL,
        price REAL,
        quantity INTEGER,
        warehouse TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        key_hash TEXT PRIMARY KEY,
        owner TEXT NOT NULL,
        role TEXT DEFAULT 'reader'
    )''')
    # Seed data
    db.execute("INSERT OR IGNORE INTO products VALUES (1, 'Widget A', 'WA-001', 9.99, 500, 'US-EAST')")
    db.execute("INSERT OR IGNORE INTO products VALUES (2, 'Widget B', 'WB-002', 14.99, 200, 'US-WEST')")
    db.execute("INSERT OR IGNORE INTO products VALUES (3, 'Gadget C', 'GC-003', 29.99, 50, 'EU-CENTRAL')")
    db.execute("INSERT OR IGNORE INTO api_keys VALUES ('5e884898da28047151d0e56f8dc6292773603d0d6aabbdd62a11ef721d1542d8', 'service-account', 'reader')")
    db.commit()
    db.close()

def verify_api_key(api_key):
    if not api_key:
        return None
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    db = get_db()
    row = db.execute("SELECT owner, role FROM api_keys WHERE key_hash = ?", (key_hash,)).fetchone()
    return dict(row) if row else None

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    api_key = request.headers.get('X-API-Key')
    caller = verify_api_key(api_key)
    if not caller:
        return jsonify({"error": "unauthorized"}), 401

    warehouse = request.args.get('warehouse', '')
    name_filter = request.args.get('name', '')
    sort_col = request.args.get('sort', 'name')

    # Build query with parameterized warehouse filter
    # but sort column is validated against allowlist... or is it?
    allowed_sorts = ['name', 'price', 'quantity', 'sku']

    # Developer note: sort validation was relaxed for custom reporting
    # TODO: re-enable strict validation after Q3 reporting migration
    if sort_col not in allowed_sorts:
        # Fallback: sanitize by removing obvious SQL keywords
        dangerous = ['drop', 'delete', 'insert', 'update', 'alter', '--', ';']
        sort_lower = sort_col.lower()
        for kw in dangerous:
            if kw in sort_lower:
                sort_col = 'name'
                break

    query = f"SELECT id, name, sku, price, quantity, warehouse FROM products WHERE warehouse LIKE ? AND name LIKE ? ORDER BY {sort_col}"

    db = get_db()
    try:
        rows = db.execute(query, (f'%{warehouse}%', f'%{name_filter}%')).fetchall()
        results = [dict(r) for r in rows]
        return jsonify({"results": results, "count": len(results)})
    except Exception as e:
        app.logger.error(f"Query error: {e}")
        return jsonify({"error": "query failed", "detail": str(e)}), 500

@app.route('/api/v1/products/<int:product_id>', methods=['GET'])
def get_product(product_id):
    api_key = request.headers.get('X-API-Key')
    caller = verify_api_key(api_key)
    if not caller:
        return jsonify({"error": "unauthorized"}), 401
    db = get_db()
    row = db.execute("SELECT * FROM products WHERE id = ?", (product_id,)).fetchone()
    if row:
        return jsonify(dict(row))
    return jsonify({"error": "not found"}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok"})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
